INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 7, 'Cross-Border Transfers', 'Section 72 Gateways', 1, 'Does the organisation assess cross-border data transfers against Section 72 gateways?', 'Section 72 provides 5 gateways for lawful cross-border data transfers. Each transfer must satisfy one of these gateways.', 'POPIA Section 72 cross-border transfers; Information Regulator cross-border guidance; ISO 27701 cl.7.11 cross-border transfers', 'Critical', 'Cross-border transfer assessment process; gateway evaluation checklist; transfer documentation; legal review of transfers; risk assessment for transfers.', 'Implement Section 72 gateway assessment process. Evaluate all cross-border transfers against the 5 gateways. Document assessment decisions.', 'P7_CBT_1'),
('popia', 7, 'Cross-Border Transfers', 'Section 72 Gateways', 2, 'Are adequate protection measures in place for cross-border transfers?', 'Section 72 requires adequate protection measures for personal information transferred across borders.', 'POPIA Section 72 adequate protection; ISO 27701 cl.7.11 cross-border transfers; Standard Contractual Clauses', 'Critical', 'Adequate protection evaluation; SCC implementation records; data processing agreements; legal review of protection measures; transfer documentation.', 'Evaluate protection measures in destination countries. Implement Standard Contractual Clauses where required. Maintain DPA documentation.', 'P7_CBT_2'),
('popia', 7, 'Cross-Border Transfers', 'Section 72 Gateways', 3, 'Are binding agreements in place for cross-border data transfers?', 'Section 72 allows cross-border transfers based on binding agreements between the parties.', 'POPIA Section 72 binding agreements; ISO 27701 cl.7.11 cross-border transfers; Standard Contractual Clauses', 'High', 'Data processing agreements with international partners; SCC implementation records; agreement review and approval processes; legal review of agreements.', 'Implement data processing agreements for international data transfers. Use approved Standard Contractual Clauses. Establish agreement review processes.', 'P7_CBT_3'),
('popia', 7, 'Cross-Border Transfers', 'Section 72 Gateways', 4, 'Are cross-border transfers of special personal information evaluated with additional safeguards?', 'Special personal information transfers require additional safeguards under Section 72.', 'POPIA Section 72 special personal information; ISO 27701 cl.7.11 cross-border transfers; Standard Contractual Clauses', 'Critical', 'Special PI transfer evaluation procedures; enhanced protection measures; additional consent requirements; legal authorisation documentation.', 'Implement enhanced evaluation for special personal information transfers. Obtain additional consent where required. Document additional safeguards.', 'P7_CBT_4'),
('popia', 7, 'Cross-Border Transfers', 'Children''s Data', 5, 'Are cross-border transfers of children''s data evaluated with additional safeguards?', 'Children''s data requires additional protection under Section 72 and other legislation.', 'POPIA Section 72 children''s data; ISO 27701 cl.7.11 cross-border transfers; Child Protection Act; GDPR Article 8 children''s data', 'Critical', 'Children''s data transfer evaluation procedures; enhanced protection measures; parental consent procedures; legal authorisation documentation; risk assessment for children''s data.', 'Implement enhanced evaluation for children''s data transfers. Obtain parental consent where required. Document additional safeguards and risk assessments.', 'P7_CBT_5'),
('popia', 7, 'Cross-Border Transfers', 'Onward Transfer Restrictions', 6, 'Are onward transfers of personal information restricted appropriately?', 'Section 72 requires that personal information not be transferred to third countries without appropriate protection.', 'POPIA Section 72 onward transfers; ISO 27701 cl.7.11 cross-border transfers; Standard Contractual Clauses; onward transfer clauses', 'High', 'Onward transfer restrictions in agreements; third-party due diligence; onward transfer consent processes; monitoring of onward transfers.', 'Include onward transfer restrictions in data processing agreements. Conduct due diligence on third parties. Obtain consent for onward transfers where required.', 'P7_CBT_6'),
('popia', 7, 'Cross-Border Transfers', 'Record-Keeping', 7, 'Are cross-border transfer activities documented comprehensively?', 'Section 72 requires organisations to maintain records of cross-border transfer activities.', 'POPIA Section 72 documentation; ISO 27701 cl.7.11 cross-border transfers; record retention requirements', 'Medium', 'Cross-border transfer documentation; transfer register; DPA file maintenance; retention schedule for transfer records.', 'Maintain comprehensive documentation of all cross-border transfer activities. Implement transfer register and DPA file management. Establish retention schedule.', 'P7_CBT_7'),
('popia', 7, 'Cross-Border Transfers', 'Record-Keeping', 8, 'Are cross-border transfer reviews conducted regularly?', 'Regular reviews of cross-border transfers ensure ongoing compliance with changing requirements.', 'POPIA Section 72 compliance monitoring; ISO 27701 cl.7.11 cross-border transfers; regulatory change monitoring', 'Medium', 'Transfer review schedule; regulatory change monitoring; compliance assessment updates; documentation of review outcomes.', 'Implement regular review schedule for cross-border transfers. Monitor regulatory changes. Update practices based on changes.', 'P7_CBT_8');